USE [BDCAPAS]
GO
SET NOCOUNT ON;

DECLARE @textos TABLE (CLAVE VARCHAR(100) PRIMARY KEY, ES NVARCHAR(400), EN NVARCHAR(400), PT NVARCHAR(400));

IF NOT EXISTS (SELECT 1 FROM IDIOMA WHERE NOMBRE LIKE 'Ingl%' OR NOMBRE = 'English')
IF NOT EXISTS (SELECT 1 FROM IDIOMA WHERE NOMBRE LIKE 'Portugu%')

DECLARE @esId  INT = COALESCE((SELECT TOP 1 ID FROM IDIOMA WHERE PREDETERMINADO = 1 ORDER BY ID),
                              (SELECT TOP 1 ID FROM IDIOMA WHERE NOMBRE LIKE 'Espa%' ORDER BY ID));
DECLARE @ingId INT = (SELECT TOP 1 ID FROM IDIOMA WHERE NOMBRE LIKE 'Ingl%' OR NOMBRE = 'English' ORDER BY ID);
DECLARE @ptId  INT = (SELECT TOP 1 ID FROM IDIOMA WHERE NOMBRE LIKE 'Portugu%' ORDER BY ID);

DECLARE @porIdioma TABLE (IDIOMA_ID INT, CLAVE VARCHAR(100), TEXTO NVARCHAR(400));

BEGIN TRANSACTION;

DELETE tr FROM TRADUCCION tr
JOIN CONTROL_IDIOMA c ON c.ID = tr.CONTROL_ID
WHERE NOT EXISTS (SELECT 1 FROM @textos t WHERE t.CLAVE = c.CLAVE);

DELETE c FROM CONTROL_IDIOMA c
WHERE NOT EXISTS (SELECT 1 FROM @textos t WHERE t.CLAVE = c.CLAVE);

UPDATE c SET TEXTO_DEFAULT = t.ES
FROM CONTROL_IDIOMA c JOIN @textos t ON t.CLAVE = c.CLAVE;

SELECT t.CLAVE, t.ES FROM @textos t
WHERE NOT EXISTS (SELECT 1 FROM CONTROL_IDIOMA c WHERE c.CLAVE = t.CLAVE);

UPDATE tr SET TEXTO = pi.TEXTO
FROM TRADUCCION tr
JOIN CONTROL_IDIOMA c ON c.ID = tr.CONTROL_ID
JOIN @porIdioma pi ON pi.CLAVE = c.CLAVE AND pi.IDIOMA_ID = tr.IDIOMA_ID;

SELECT pi.IDIOMA_ID, c.ID, pi.TEXTO
FROM @porIdioma pi
JOIN CONTROL_IDIOMA c ON c.CLAVE = pi.CLAVE
WHERE NOT EXISTS (SELECT 1 FROM TRADUCCION tr WHERE tr.IDIOMA_ID = pi.IDIOMA_ID AND tr.CONTROL_ID = c.ID);

COMMIT TRANSACTION;

SELECT i.NOMBRE AS IDIOMA, COUNT(tr.CONTROL_ID) AS TRADUCCIONES
FROM IDIOMA i LEFT JOIN TRADUCCION tr ON tr.IDIOMA_ID = i.ID
GROUP BY i.NOMBRE;
GO
